function flattenPages(pages) {
  if (!pages.length || pages.length > 10) throw new Error('Expected 1–10 Famulor response pages.');
  const total = pages[0]?.meta?.pagination?.total;
  if (!Number.isSafeInteger(total) || total < 0) throw new Error('Missing or invalid Famulor result count.');
  if (total > 2000) throw new Error('More than 2,000 records. Narrow the date window.');
  const rows = [];
  let expectedOffset = 0;
  for (const page of pages) {
    if (page.error || !Array.isArray(page.data)) throw new Error('Famulor returned an invalid response. Check the credential and read scope.');
    const p = page.meta?.pagination;
    if (!p || p.total !== total || p.limit !== 200 || p.offset !== expectedOffset || page.data.length > 200) {
      throw new Error('Incomplete or inconsistent Famulor pagination. No destination data was written.');
    }
    rows.push(...page.data);
    expectedOffset += 200;
  }
  if (rows.length !== total) throw new Error('The Famulor scan was incomplete or changed while paging. No destination data was written.');
  const ids = rows.map(row => row?.id);
  if (ids.some(value => typeof value !== 'string' || !value.trim()) || new Set(ids).size !== ids.length) {
    throw new Error('Missing or duplicate record IDs. No destination data was written.');
  }
  return rows;
}
const rows=flattenPages($input.all().map(i=>i.json));

const cfg=$('Build date window').first().json;
const start=Date.parse(cfg.windowStart),end=Date.parse(cfg.windowEnd);
if (!Number.isFinite(start)||!Number.isFinite(end)||end<=start) throw new Error('Invalid configured date range.');

const selected=rows.filter(r=>Date.parse(r.created_at)>=start&&Date.parse(r.created_at)<end);
const counts={completed:0,failed:0,no_answer:0,busy:0,queued:0,ringing:0,in_progress:0,other:0};
let seconds=0,negative=0,scored=0,successful=0;
for(const r of selected){counts[Object.hasOwn(counts,r.status)?r.status:'other']++;if(Number.isFinite(r.duration_sec)&&r.duration_sec>=0)seconds+=r.duration_sec;if((r.sentiment??r.analysis?.sentiment)==='negative')negative++;if(typeof r.success==='boolean'){scored++;if(r.success)successful++;}}
const text=[
  'Famulor daily call report',
  'Creation window: '+cfg.windowStart+' to '+cfg.windowEnd+' (end excluded)',
  'Calls: '+selected.length+' | Completed: '+counts.completed+' | Failed: '+counts.failed,
  'No answer: '+counts.no_answer+' | Busy: '+counts.busy+' | Still active/queued: '+(counts.queued+counts.ringing+counts.in_progress),
  'Voice minutes: '+(seconds/60).toFixed(2)+' | Negative sentiment: '+negative,
  'Analyzed success: '+successful+'/'+scored+(scored?' ('+(successful/scored*100).toFixed(1)+'%)':' (no success analysis available)'),
  'Calls created in this window may finish later. This is a creation-cohort report, not a completion or billing report.',
].join('\n');
return [{json:{text,totalCalls:selected.length,counts,voiceMinutes:Number((seconds/60).toFixed(2)),negativeCalls:negative,scoredCalls:scored,successfulCalls:successful}}];
